(function(root){
const TYPES={MAIN:{name:'Wyłącznik główny',short:'FR',width:4,rating:'40 A',poles:['L1','L2','L3','N']},RCD:{name:'Wyłącznik różnicowy',short:'RCD',width:4,rating:'40 A / 30 mA',poles:['L1','L2','L3','N']},MCB:{name:'Wyłącznik nadprądowy',short:'MCB',width:1,rating:'B16',poles:['L']},RCBO:{name:'Wyłącznik różnicowo-nadpr.',short:'RCBO',width:2,rating:'B16 / 30 mA',poles:['L','N']},SPD:{name:'Ogranicznik przepięć',short:'SPD',width:4,rating:'Model ogólny',poles:['L1','L2','L3','N'],bottom:['PE']},N:{name:'Listwa neutralna',short:'N',width:3,rating:'Listwa N',poles:['N','N','N'],bottom:['N','N','N']},PE:{name:'Listwa ochronna',short:'PE',width:3,rating:'Listwa PE',poles:['PE','PE','PE'],bottom:['PE','PE','PE']}};
const ports=c=>['t','b'].flatMap(side=>(side==='b'?(TYPES[c.type].bottom||TYPES[c.type].poles):TYPES[c.type].poles).map((role,i)=>({key:side+i,role,side,i,count:(side==='b'?(TYPES[c.type].bottom||TYPES[c.type].poles):TYPES[c.type].poles).length})));
const getPort=(s,e)=>{const c=s.components.find(c=>c.id===e.device);return c&&ports(c).find(p=>p.key===e.port)};
const fits=(s,c,row,slot)=>Number.isInteger(row)&&row>=0&&row<4&&Number.isInteger(slot)&&slot>=0&&slot+TYPES[c.type].width<=18&&!s.components.some(x=>x.id!==c.id&&x.row===row&&slot<x.slot+TYPES[x.type].width&&slot+TYPES[c.type].width>x.slot);
function canConnect(s,a,b){if(!getPort(s,a)||!getPort(s,b))return 'Nieznany zacisk';if(a.device===b.device)return 'W prototypie nie łączymy zacisków tego samego aparatu';if(s.wires.some(w=>(same(w.a,a)&&same(w.b,b))||(same(w.a,b)&&same(w.b,a))))return 'Te zaciski są już połączone';return null}
const same=(a,b)=>a.device===b.device&&a.port===b.port;
function validate(s){let out=[];if(!s.components.length)return[{severity:'warn',title:'Pusta rozdzielnia',text:'Dodaj aparaty z katalogu.'}];for(const c of s.components){if(!fits(s,c,c.row,c.slot))out.push({severity:'error',device:c.id,title:'Kolizja aparatów',text:c.label+': sprawdź pozycję na szynie.'});const free=ports(c).filter(p=>!s.wires.some(w=>same(w.a,{device:c.id,port:p.key})||same(w.b,{device:c.id,port:p.key})));if(free.length)out.push({severity:'warn',device:c.id,title:'Zaciski bez przewodu · '+c.label,text:free.length+' zacisków bez połączenia. Mogą być celowo wolne; sprawdź przeznaczenie.'});}
for(const w of s.wires){const a=getPort(s,w.a),b=getPort(s,w.b);if(!a||!b){out.push({severity:'error',wire:w.id,title:'Nieznany zacisk',text:'Połączenie odwołuje się do brakującego zacisku.'});continue;}const f=r=>r.startsWith('L')?'L':r;const roles=[a.role,b.role];if(f(a.role)!==f(b.role))out.push({severity:'error',wire:w.id,title:'Różne funkcje zacisków',text:roles.join(' ↔ ')+'. Sprawdź to połączenie; rozdział PEN nie jest obsługiwany.'});else if(a.role.startsWith('L')&&b.role.startsWith('L')&&a.role!=='L'&&b.role!=='L'&&a.role!==b.role)out.push({severity:'error',wire:w.id,title:'Połączono różne fazy',text:roles.join(' ↔ ')});if(roles.some(r=>f(r)!==f(w.role)))out.push({severity:'error',wire:w.id,title:'Niespójna funkcja żyły',text:'Żyła '+w.role+' nie odpowiada funkcji jednego z zacisków.'});}
return out;}
function parse(data){if(!data||data.version!==1||typeof data.name!=='string'||data.name.length>120||!Array.isArray(data.components)||data.components.length>72||!Array.isArray(data.wires)||data.wires.length>500||!Array.isArray(data.circuits)||data.circuits.length>150)throw Error('Nieprawidłowy format projektu DIN Studio.');const s=JSON.parse(JSON.stringify(data));const ids=new Set();for(const c of s.components){if(!c||!Object.hasOwn(TYPES,c.type)||typeof c.id!=='string'||!(/^[a-zA-Z0-9_-]{1,80}$/).test(c.id)||ids.has(c.id)||typeof c.label!=='string'||c.label.length>60||typeof c.rating!=='string'||c.rating.length>100||typeof c.on!=='boolean')throw Error('Nieprawidłowy aparat.');ids.add(c.id);if(!fits(s,c,c.row,c.slot))throw Error('Aparaty zachodzą na siebie lub poza szynę.');}const wi=new Set();for(const w of s.wires){if(!w||typeof w.id!=='string'||!(/^[a-zA-Z0-9_-]{1,80}$/).test(w.id)||wi.has(w.id)||!w.a||!w.b||!getPort(s,w.a)||!getPort(s,w.b)||w.a.device===w.b.device||!['L','L1','L2','L3','N','PE'].includes(w.role)||![1.5,2.5,4,6,10,16].includes(w.gauge))throw Error('Nieprawidłowe połączenie.');wi.add(w.id);}const ci=new Set();for(const c of s.circuits){if(!c||typeof c.id!=='string'||!(/^[a-zA-Z0-9_-]{1,80}$/).test(c.id)||ci.has(c.id)||typeof c.name!=='string'||c.name.length>120||typeof c.device!=='string'||(c.device&&!ids.has(c.device))||!Number.isFinite(c.power)||c.power<0||typeof c.cable!=='string'||c.cable.length>60)throw Error('Nieprawidłowy obwód.');ci.add(c.id);}return s;}
const api={TYPES,ports,getPort,fits,canConnect,validate,parse};if(typeof module!=='undefined')module.exports=api;root.DIN=api;
})(typeof window!=='undefined'?window:globalThis);
